"""Exact author calculations and enumerations tied to literal selected contents; not academic certification."""
import json,hashlib,itertools,math
from pathlib import Path
import sympy as s
R=Path(__file__).resolve().parents[2];O=R/'IISER/review/tests24_25';docs={t:json.loads((R/f'IISER/IAT NEW TEST {t}.json').read_text()) for t in [24,25]};rows=[];F=s.Rational
x,a=s.symbols('x a',real=True)
def check(t,n,label,value,expected,selected):
 assert value==expected or s.simplify(value-expected)==0,(t,n,label,value,expected)
 q=docs[t]['questions'][n-1];ans=q['options']['ABCD'.index(q['correct_option'])][3:];assert selected in ans,(t,n,ans,selected)
 rows.append(dict(id=q['id'],probe=label,result=str(value),expected=str(expected),selected_content=ans,passed=True))
check(24,4,'Arithmetic lineage',1+4,5,'P=5');check(24,4,'Geometric lineage',2**4,16,'Q=16')
check(25,14,'S phase window',7-2,5,'S=5');check(25,14,'Remaining G1',12-5-2-1,4,'G1=4')
check(24,16,'MO bond order',F(6-2,2),2,'Bond order 2')
check(24,18,'Internal Mn electron count',(7-6)+(7-4),4,'4 electrons')
check(24,20,'Velocity uncertainty ratio',1000/F(1836),F(250,459),'1000/1836');check(24,20,'Energy scale ratio',1000**2/F(1836),F(250000,459),'1000000/1836')
check(24,21,'Dry chloride amount',F(1148,1000)/F(1435,10),F(8,1000),'93.6');check(24,21,'NaCl purity',100*(F(1148,1000)/F(1435,10))*F(585,10)/F(1,2),F(936,10),'93.6')
check(24,27,'Bicarbonate base constant',F(1,10**14)/F(5,10**7),F(2,10**8),'2×10−8')
check(24,28,'Temperature Henry compensation',F(4,10)*2/F(2,10)/4,1,'1; no')
check(24,29,'Parallel copper mass',F(2,10)*9650/96500/2*F(635,10),F(635,1000),'0.635');check(24,29,'Parallel silver mass',F(3,10)*9650/96500*108,F(324,100),'3.240')
check(24,30,'Coupled Gibbs',2*20-50,-10,'−10')
check(25,17,'Optical mixture fraction',s.solve(60*x-60*(1-x)-15,x)[0],F(5,8),'5/8')
check(25,17,'Denticity',3*2,6,'6')
check(25,18,'Dissolution enthalpy',800-760,40,'+40');check(25,18,'Dissolution Gibbs',40-298*F(150,1000),F(-47,10),'−4.7')
check(25,19,'Outgoing collision electron energy',12-F(102,10),F(18,10),'1.8')
check(25,23,'DNA nucleotide fraction',F(8,20),F(2,5),'0.40');check(25,23,'Mixture guanine',F(2,5)*30+F(3,5)*35,33,'G33');check(25,23,'Mixture cytosine',F(2,5)*30+F(3,5)*25,27,'C27')
check(25,24,'Prefactor ratio',s.exp(s.log(100)),100,'100 times')
check(25,26,'Oxygen product',F(1,10)/2,F(1,20),'0.0500');check(25,26,'Electron equivalents',2*F(1,20),F(1,10),'0.100')
check(25,27,'Total entropy at400',48000/F(400)-100,20,'20 J');check(25,27,'Gibbs400',-48+400*F(1,10),-8,'−8');check(25,27,'Gibbs600',-48+600*F(1,10),12,'+12')
check(25,28,'Solute mass',120*F(1,5)+100*F(1,10),34,'85/44');check(25,28,'Nonadditive volume',220/F(125,100),176,'85/44');check(25,28,'Molarity',F(34,100)/F(176,1000),F(85,44),'85/44');check(25,28,'Mass percentage',F(3400,220),F(170,11),'170/11')
# All thirty Mathematics items: symbolic calculations plus independent finite enumeration.
check(24,31,'Slope product',-(F(25,9)-1),F(-16,9),'−16/9')
check(24,32,'Focal x',F(1,2)+F(3,2),2,'(2,−1)');check(24,32,'Focal y',2-2*F(3,2),-1,'(2,−1)')
f=x**x;der=s.diff(f,x);check(24,33,'Stationary derivative',der.subs(x,s.exp(-1)),0,'global minimum');check(24,33,'Positive curvature form',s.diff(f,x,2)-f*((s.log(x)+1)**2+1/x),0,'positive')
check(24,34,'Integral at proposed parameter',s.integrate(1/(1+x),(x,0,1)),s.log(2),'a=1')
f1=(x-1)/x;f2=s.factor(f1.subs(x,f1));f3=s.factor(f1.subs(x,f2));check(24,35,'Third iterate',s.factor(f3-x),0,'period 3');check(24,35,'Fixed-point discriminant',1-4,-3,'period 3')
A=s.Matrix([[1,1,0],[0,1,1],[1,0,1]]);B=A.copy();B[:,1]=A[:,1]+2*A[:,0]
check(24,36,'Updated inverse first column',sum(v**2 for v in B.inv()[:,0]-s.Matrix([F(-1,2),F(1,2),F(-1,2)])),0,'−1/2')
dice=list(itertools.product(range(1,7),repeat=3));cond=[r for r in dice if min(r)==2];check(24,37,'Dice conditional enumeration',F(sum(sum(r)==8 for r in cond),len(cond)),F(6,61),'6/61')
terms=[s.binomial(8,r)*F(-1,2)**r for r in range(9)];check(24,38,'Signed maximal term sum',terms[2]+terms[3],0,'sum 0');assert [i for i,t in enumerate(terms) if abs(t)==max(map(abs,terms))]==[2,3]
ns=[n for n in range(1,50) if sum((-1)**j*(3+2*j) for j in range(n))==11];assert ns==[9];check(24,39,'Alternating AP term',3+2*(ns[0]-1),19,'19')
check(24,40,'Exceptional parameter limit',s.limit(0/x**2,x,0),0,'0 and −1/2');check(24,40,'Nonzero parameter representative',s.limit((s.sqrt(1+2*x)-1)/(x*(x-2)),x,0),F(-1,2),'−1/2')
check(24,41,'Closest-line norm squared',F(1,4)**2+F(1,2)**2+F(1,4)**2,F(3,8),'sqrt(6)/4')
# Fix A at vertex0; B opposite; pair the remaining assignments under reflection.
arr=list(itertools.permutations('CDEF'));keys={min(tuple(p),tuple(p[i] for i in [3,2,1,0])) for p in arr};check(24,42,'Reflection quotient enumeration',len(keys),12,'12')
z,w=s.symbols('z w',nonzero=True);check(24,43,'Conjugate factor identity',s.factor((z+1/z-w-1/w)-(z-w)*(1-1/(z*w))),0,'unit circle')
c=s.symbols('c');y=(x-c)**2;check(24,44,'Positive delayed branch equation',s.diff(y,x)**2-4*y,0,'Infinitely');check(24,44,'Delayed branch derivative join',s.diff(y,x).subs(x,c),0,'Infinitely')
check(24,45,'Equality interior sample',s.asin(s.sin(s.pi/4))-s.acos(s.cos(s.pi/4)),0,'[0,pi/2]');check(24,45,'Equality isolated endpoint',s.asin(s.sin(2*s.pi))-s.acos(s.cos(2*s.pi)),0,'2pi')
check(25,31,'Eccentricity',F(1,2),F(1,2),'e=1/2');check(25,31,'Completed centre',F(1,2)/F(3,4),F(2,3),'2/3')
check(25,32,'Intercept condition fourth power',F(1,3),F(1,3),'1/3')
check(25,33,'Area boundary supremum',(x*(6-x)).subs(x,3),9,'not attained');check(25,33,'Area completed square',s.expand(x*(6-x)-(9-(x-3)**2)),0,'not attained')
r=(x**3-x**2-x+1)/((x-1)*(x*x+1));check(25,34,'Rational cancellation',s.factor(r-(x*x-1)/(x*x+1)),0,'pi−2');value=s.integrate(-(x*x-1)/(x*x+1),(x,0,1))+s.integrate((x*x-1)/(x*x+1),(x,1,2));check(25,34,'Unsigned area',value,s.pi-2*s.atan(2),'pi−2')
fmap=[1,2,0,3];gs=[g for g in itertools.product(range(4),repeat=4) if all(g[fmap[i]]==fmap[g[i]] for i in range(4))];check(25,35,'Commuting functions enumerated',len(gs),4,'4 maps');check(25,35,'Bijective commuting functions',sum(len(set(g))==4 for g in gs),3,'3 bijections')
v=s.Matrix([0,1,-1]);e1=s.Matrix([1,0,0]);check(25,36,'Vector equation residual',(v+e1.cross(v)-s.Matrix([0,2,0])).dot(v+e1.cross(v)-s.Matrix([0,2,0])),0,'e2−e3')
A=s.Matrix([[2,1],[0,2]]);check(25,37,'Matrix trace',(A**6).trace(),128,'128');check(25,37,'Matrix entry ratio',(A**6)[0,1]/(A**6)[0,0],3,'n=6')
pairs=[(a,b) for a,b in itertools.permutations(range(1,6),2) if a+b>=6];check(25,38,'Stopping report enumeration',F(sum(a==5 for a,b in pairs),len(pairs)),F(1,3),'1/3')
committees=[c for c in itertools.combinations(range(12),4) if sum(2*i in c and 2*i+1 in c for i in range(6))==1];check(25,39,'Committee enumeration',len(committees),240,'240')
p=s.Poly(s.expand((1+x)**5*sum((-x)**j for j in range(11))),x);check(25,40,'Finite polynomial coefficient difference',p.nth(12)-p.nth(10),4,'4')
check(25,41,'Signed GP ratio',F(-6,3),-2,'r=−2');check(25,41,'Signed GP sum',sum(3*(-2)**j for j in range(4)),-15,'−15')
check(25,42,'Conjugate modulus product',(1+s.I*s.sqrt(3))*(1-s.I*s.sqrt(3)),4,'a=1');check(25,42,'Positive-root argument',s.arg(1+s.I*s.sqrt(3)),s.pi/3,'pi/3')
check(25,43,'Attaining mean',F(-2-2-2+3+3,5),0,'12/5');check(25,43,'Attaining mean deviation',F(2+2+2+3+3,5),F(12,5),'12/5')
y=2*s.log(x);check(25,44,'ODE substitution',s.simplify(s.diff(y,x)-y/(x*s.log(x))),0,'2 ln x');check(25,44,'Initial condition',y.subs(x,s.E),2,'2 ln x')
check(25,45,'Inverse left derivative at join',s.diff(s.sqrt(x),x).subs(x,1),F(1,2),'1/2');check(25,45,'Inverse endpoint divergence',s.limit(1/s.sqrt(x),x,0,dir='+'),s.oo,'no finite')
